#if NET6_0_OR_GREATER
using FirmarOnline.Model.PSC.Forms; 
#endif
using System.Collections.Generic;
using System.Linq;

namespace FirmarOnline.Model.PSC.Tests
{
    internal static class SampleValuesHelper
    {
        internal const string DocumentPdfB64 = "";

#if NET6_0_OR_GREATER
        internal static Form DocumentForm => new()
        {           
            // GeneralStyles = new List<GeneralStyle>(),
            Pages = new List<Page>
            {
                new Page
                {
                    Items = new List<ItemBase>()
                }
            }
        };
#endif

        internal static DocumentColletion DocumentColletionWithPdf(int count = 1)
        {
            var coll = new DocumentColletion();
            coll.AddRange(Enumerable.Range(1, count).Select(n => new Document
            {
                Id = $"doctest{n:D2}",
                Name = $"Test Document {n}",
                B64PDFContent = DocumentPdfB64
            }));
            return coll;
        }

        internal static Document DocumentWithPdf => new()
        {
            Name = "Test Document PDF",
            B64PDFContent = DocumentPdfB64
        };

#if NET6_0_OR_GREATER
        internal static Document DocumentWithForm => new()
        {
            Name = "Test Document Form",
            Form = DocumentForm
        };
#endif

        internal static Document DocumentWithFormTemplate => new()
        {
            Name = "Test Document Form",
            FormId = "335603D9E87E4C8686DAD5839F13C374"
        };

        internal static Document DocumentWithFormId(string id = "WF-1") => new()
        {
            Name = "Test WebForm",
            FormId = id
        };

        internal static SingleDocumentRecipient SingleDocumentRecipient => new()
        {
            Name = "Test recipient",
            Email = "testrecipient@foo.com",
            AuthType = RecipientAuthenticationType.None,
            ActionType = RecipientActionType.BioSignature // evita SMS en tests
        };

        internal static RecipientCollection<Recipient> RecipientColletion(int count = 1)
        {
            var coll = new RecipientCollection<Recipient>();
            coll.AddRange(Enumerable.Range(1, count).Select(n => new Recipient
            {
                Id = $"doctest{n:D2}",
                Name = $"Test Document {n}",
                Email = $"testrecipient{n:D2}@foo.com",
                AuthType = RecipientAuthenticationType.Basic,
                ActionType = RecipientActionType.Acceptance,
                // Widgets = Enumerable.Range(1, count).Select(m => new RecipientAction { DocumentId = $"doctest{m:D2}" }).ToList()
            }));
            return coll;
        }

        internal static RecipientCollection<RecipientFlow> RecipientFlowColletion(int count = 1)
        {
            var coll = new RecipientCollection<RecipientFlow>();
            coll.AddRange(Enumerable.Range(1, count).Select(n => new RecipientFlow
            {
                Id = $"doctest{n:D2}",
                Name = $"Test Document {n}",
                Email = $"testrecipient{n:D2}@foo.com",
            }));
            return coll;
        }
    }
